def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda c: sum(row.count(c) for row in grid))
    marker_cols = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]
    if not marker_cols:
        return grid
    marker = marker_cols[0]

    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, 2)]
    if not cells:
        return grid

    minc = min(c for _, c, _ in cells)
    maxc = max(c for _, c, _ in cells)
    shift = marker + 1 - minc

    out = [row[:] for row in grid]
    for r, c, _ in cells:
        out[r][c] = bg
    for r, c, color in cells:
        nc = c + shift
        if 0 <= nc < w:
            out[r][nc] = color

    stripe = maxc + shift + 1
    if 0 <= stripe < w:
        for r in range(h):
            out[r][stripe] = 8
    return out
